import React, { useState, useEffect } from 'react';
import axios from 'axios';

export default function Timetable() {
  const [classes, setClasses] = useState([]);

  // 🟢 ඩේටාබේස් එකෙන් ලයිව් ටයිම් ටේබල් දත්ත ඇදගැනීම
  useEffect(() => {
    axios.get('http://localhost:8082/api/timetable')
      .then(res => {
        setClasses(Array.isArray(res.data) ? res.data : []);
      })
      .catch(err => console.log("Public Timetable Fetch Error:", err));
  }, []);

  return (
    <div style={{ padding: '60px 20px', backgroundColor: '#f8fafc', flex: 1, fontFamily: 'sans-serif' }}>
      <div style={{ maxWidth: '1000px', margin: '0 auto', textAlign: 'center' }}>
        
        <h1 style={{ color: '#15803d', fontSize: '32px', fontWeight: 'bold', margin: '0 0 10px 0' }}>
          Aura Pen Education
        </h1>
        <p style={{ color: '#64748b', fontSize: '15px', margin: '0 0 40px 0' }}>
          Official Class Timetable - Mirigama
        </p>

        <div style={{ backgroundColor: 'white', padding: '25px', borderRadius: '16px', boxShadow: '0 4px 20px rgba(0,0,0,0.03)', overflowX: 'auto' }}>
          <table style={{ width: '100%', borderCollapse: 'collapse', textAlign: 'left' }}>
            <thead>
              <tr style={{ backgroundColor: '#15803d', color: 'white' }}>
                <th style={{ padding: '14px 18px', borderRadius: '8px 0 0 8px', fontWeight: 'bold' }}>Day</th>
                <th style={{ padding: '14px 18px', fontWeight: 'bold' }}>Grade</th>
                <th style={{ padding: '14px 18px', fontWeight: 'bold' }}>Subject</th>
                <th style={{ padding: '14px 18px', fontWeight: 'bold' }}>Time Window</th>
                <th style={{ padding: '14px 18px', borderRadius: '0 8px 8px 0', fontWeight: 'bold' }}>Teacher</th>
              </tr>
            </thead>
            <tbody>
              {classes.length > 0 ? (
                // අලුත්ම පන්ති වගුවේ උඩටම එන ලෙස සකසා ඇත
                [...classes].map((c) => (
                  <tr key={c.id} style={{ borderBottom: '1px solid #f1f5f9', transition: '0.2s' }}>
                    <td style={{ padding: '16px 18px', fontWeight: 'bold', color: '#1e293b' }}>{c.day}</td>
                    <td style={{ padding: '16px 18px', color: '#475569' }}>{c.grade}</td>
                    <td style={{ padding: '16px 18px', color: '#0284c7', fontWeight: '600' }}>{c.subject}</td>
                    <td style={{ padding: '16px 18px', color: '#ea580c', fontWeight: '500' }}>{c.time_slot}</td>
                    <td style={{ padding: '16px 18px', color: '#15803d', fontWeight: 'bold' }}>{c.teacher}</td>
                  </tr>
                ))
              ) : (
                <tr>
                  <td colSpan="5" style={{ padding: '40px 18px', textAlign: 'center', color: '#94a3b8', fontSize: '14px' }}>
                    📭 No institutional classes scheduled in the live database matrix yet.
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>

      </div>
    </div>
  );
}
